interaction.detection:
window.addEventListener('devicemotion', (e) => {
  let delta = Math.abs(lastX - e.accelerationIncludingGravity.x) + Math.abs(lastY - e.accelerationIncludingGravity.y);
  if (delta > 15) triggerEraserAnimation();
});

agent.chalk_brush_algorithm:
class ChalkBrush {
  constructor(ctx, color = '#F5F5F0') {
    this.bristles = generateBristles(12); // offsetX, offsetY, opacity, size
  }

  draw(x, y, pressure = 1) {
    bristles.forEach(b => {
      ctx.arc(x + b.offsetX*pressure, y + b.offsetY*pressure, b.size*pressure, 0, 2π);
      ctx.fillStyle = rgba(245,245,240, b.opacity*pressure);
    });
  }

  stroke(fromX, fromY, toX, toY, pressure) {
    const steps = Math.ceil(distance / 2);
    for (let i = 0; i <= steps; i++) {
      draw(lerp(from, to, i/steps), pressure);
    }
  }
}

