agent.gemini_api_integration:
Workflow:
1. User clicks "Export to LaTeX"
2. Canvas exports as PNG base64
3. Loading state shows proof-writing animation
4. API call with system prompt:
   "Transcribe all mathematical notation in this handwritten image to 
   properly formatted LaTeX. Use appropriate environments. Return only 
   LaTeX code with no explanation or markdown."
5. Response displayed in preview modal with KaTeX rendering
6. User can copy LaTeX or download .tex file

Implementation:
import { GoogleGenerativeAI } from '@google/generative-ai';
const genAI = new GoogleGenerativeAI(process.env.NEXT_PUBLIC_GEMINI_API_KEY);

async function transcribeToLatex(imageBase64) {
  const model = genAI.getGenerativeModel({ model: 'gemini-1.5-flash' });
  const result = await model.generateContent([prompt, { inlineData: { mimeType: 'image/png', data: imageBase64 }}]);
  return result.response.text();
}

agent.page_transitions:
// PageTransition.tsx
const handleRouteChangeStart = () => {
  gsap.to(currentPage, { x: '-5%', opacity: 0.3, scale: 0.98, duration: 0.4, ease: 'power2.in' });
};

const handleRouteChangeComplete = () => {
  gsap.fromTo(newPage,
    { x: '5%', opacity: 0, scale: 0.98 },
    { x: '0%', opacity: 1, scale: 1, duration: 0.6, ease: 'power2.out', clearProps: 'all' }
  );
};

agent.scroll_animations:
// useIntersectionAnimation.ts
useEffect(() => {
  const elements = document.querySelectorAll('[data-animate]');

  elements.forEach(el => {
    gsap.fromTo(el,
      { opacity: 0, y: 30 },
      {
        opacity: 1, y: 0, duration: 0.6, ease: 'power2.out',
        scrollTrigger: { trigger: el, start: 'top 85%', toggleActions: 'play none none reverse' }
      }
    );
  });
}, []);

Stagger children: delay 0.1s between items
Gothic elements: draw-in animation on scroll into view

