agent.reduced_motion:
// Respect prefers-reduced-motion
const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

if (prefersReducedMotion) {
  gsap.globalTimeline.timeScale(0); // Disable all animations
  // Use instant state changes instead
}

// CSS fallback
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

agent.particle_system:
// ChalkDustParticles.ts
class ParticleSystem {
  particles: Particle[] = [];

  emit(x, y, count = 30) {
    for (let i = 0; i < count; i++) {
      const particle = createParticle(x, y);
      this.particles.push(particle);

      gsap.to(particle.element, {
        physics2D: {
          velocity: 50 + Math.random() * 50,
          angle: Math.random() * 360,
          gravity: 50,
          friction: 0.1
        },
        opacity: 0,
        duration: 1.5 + Math.random(),
        onComplete: () => this.remove(particle)
      });
    }
  }
}

