agent.github_pages_deployment:
// .github/workflows/deploy.yml name: Deploy to GitHub Pages
on: push: branches: [main]
jobs: build-and-deploy: runs-on: ubuntu-latest steps: - uses: actions/checkout@v4
- name: Setup Node uses: actions/setup-node@v4 with: node-version: '20' cache: 'npm'
- name: Install dependencies run: npm ci
- name: Build run: npm run build env: NEXT_PUBLIC_GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}
- name: Export static run: npm run export
- name: Deploy to GitHub Pages uses: peaceiris/actions-gh-pages@v3 with: github_token: ${{ secrets.GITHUB_TOKEN }} publish_dir: ./out
next.config.js: module.exports = { output: 'export', images: { unoptimized: true }, basePath: process.env.NODE_ENV === 'production' ? '/portfolio' : '', assetPrefix: process.env.NODE_ENV === 'production' ? '/portfolio/' : '', };
